<script setup lang="ts">
import { computed, ref, type Component } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { useAuthStore } from './stores/authStore'; import { BookOpen,CalendarDays,CheckSquare,GraduationCap,Home,Menu,Users,X,LogOut } from 'lucide-vue-next';
const route=useRoute(),router=useRouter(),auth=useAuthStore(),open=ref(false); const publicPage=computed(()=>Boolean(route.meta.public));
const navigation: Array<{to:string;label:string;icon:Component}>=[{to:'/dashboard',label:'Tổng quan',icon:Home},{to:'/lop-hoc',label:'Lớp học',icon:GraduationCap},{to:'/diem-danh',label:'Điểm danh',icon:CheckSquare},{to:'/bai-tap',label:'Bài tập',icon:BookOpen},{to:'/thieu-nhi',label:'Thiếu nhi',icon:Users},{to:'/lich-hoc',label:'Lịch học',icon:CalendarDays}];
async function signOut(){await auth.logout();await router.push('/login');}
</script>
